// 🧵 Pocket must remain unchanged here.
import "./types.nui" as types
import "./module.nui" as pattern
style Ink {
  width: 1px,
  color: #123456,
}
instance provider = types::Provider()
const rootEdit: number = 0 // independently current, never saved
const first: types::Measure = types::Measure(x: @provider::out.x + @rootEdit, y: @provider::out.y)
group Left [Ink] {
  instance piece = pattern::PocketRenamed(measure: @first, shift: 3)
}

group Control [Ink] {
  line Edge = segment(start: (-3, 2), end: (10, 7))
}
group Excluded [Ink] {
  line NotSelected = segment(start: (601, -607), end: (613, -619))
}
layout Sheet {
  place @Left(at: (7, -11), scale: 2, angle: 90, mirror: false)
  place @Control(at: (260, -40), scale: 1, angle: 0, mirror: false)
}
layout Unselected {
  place @Excluded(at: (0, 0))
}
svg WrongVector(layout: @Unselected, layers: [@default], margin: 0)
print WrongPaper(layout: @Unselected, layers: [@default], paper: a3, overlap: 0)
svg Vector(layout: @Sheet, layers: [@default], margin: 3)
print Paper(layout: @Sheet, layers: [@default], paper: a4, overlap: 10)
// End sentinel Pocket.

